import abc
import six


@six.add_metaclass(abc.ABCMeta)
class Core(object):

    @abc.abstractmethod
    def change_configuration_file(self, config_file):
        pass

    @abc.abstractmethod
    def restart_configuration(self):
        pass

    @abc.abstractmethod
    def start_paging(self):
        pass

    @abc.abstractmethod
    def stop_paging(self):
        pass

    @abc.abstractmethod
    def collect_configuration(self, log_dir):
        pass

    @abc.abstractmethod
    def start_recovery_observers(self):
        pass

    @abc.abstractmethod
    def stop_recovery_observers(self):
        pass

    @abc.abstractmethod
    def get_version(self):
        pass
